  "id": "oabconselhofederal-2025-ac3",
  "tipo": "sentenca",
  "peca": "Peça / sentença",
  "carreira": "OAB 2ª fase",
  "area": "Jurídica",
  "subarea": "OAB 2ª fase",
  "banca": "FGV",
  "orgao": "OAB / Conselho Federal",
  "cargo": "Exame de Ordem Unificado - 2ª fase (prova prático-profissional)",
  "ano": 2025,
