  "fonte": "https://cdn.cebraspe.org.br/concursos/BCB_24/arquivos/BCB_24_PADRO_DE_RESPOSTA_DEFINITIVO_CARGO_2_ATUALIZADO.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/BCB_24/arquivos/BCB_PROVA_DISCURSIVA_CARGO_1.PDF",
