  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_25_AUDITOR/arquivos/58612C587C74A76CFD5DFAD1594F03014DC5080DA6BF143DA73251955B8E7297.pdf",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_25_AUDITOR/arquivos/292EC4437C3D9F4B4D1C8F4D6A254D9B9C260620E49574088C6781CFBA641F3F.pdf",
