  "fonte": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_21_AUDITOR/arquivos/SEFAZ_SE_21_AUDITOR_PADRO_DE_RESPOSTA_DEFINITIVO_CF.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_21_AUDITOR/arquivos/780_SEFAZ_CP_DISC_001.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_21_AUDITOR/arquivos/SEFAZ_SE_21_AUDITOR_PADRO_DE_RESPOSTA_DEFINITIVO_CF.PDF",
  "fonte_concurso": "https://www.cebraspe.org.br/concursos/SEFAZ_SE_21_AUDITOR",
