  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_21_AUDITOR/arquivos/667_SEFAZ_SE_DISC002.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/SEFAZ_SE_21_AUDITOR/arquivos/SEFAZ_SE_21_AUDITOR_PADRO_DE_RESPOSTA_DEFINITIVO_ESTUDO_DE_CASO.PDF",
