  "fonte": "https://cdn.cebraspe.org.br/concursos/SEFAZ_AL_19_AUDITOR/arquivos/SEFAZAL515002A01E3079_PADRAORESPOSTA_CARGO_2_ESTUDO_DE_CASO_I.DOCX.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/SEFAZ_AL_19_AUDITOR/arquivos/515_SEFAZAL_002_01_DISC.PDF",
