  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/TCE_RJ_21_TECNICO/arquivos/680_TCERJTECNICO_002_DISC.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/TCE_RJ_21_TECNICO/arquivos/TCE_RJ_21_TECNICO_PADRO_DE_RESPOSTA_DEFINITIVO_COMPLETO.PDF",
