  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/TCE_SC_21_AUDITOR/arquivos/660_TCESC_006_DISC.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/TCE_SC_21_AUDITOR/arquivos/TCE_SC_21_AUDITOR_PADRO_DE_RESPOSTA_DEFINITIVO_CARGO_06.PDF",
