  "fonte": "https://cdn.cebraspe.org.br/concursos/TRT8_22/arquivos/TRT8_22_PADRO_DE_RESPOSTA_DEFINITIVO_CARGO_7.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/TRT8_22/arquivos/759_TRT8_007_DISC.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/TRT8_22/arquivos/TRT8_22_PADRO_DE_RESPOSTA_DEFINITIVO_CARGO_7.PDF",
  "fonte_concurso": "https://www.cebraspe.org.br/concursos/TRT8_22",
