  "fonte": "https://cdn.cebraspe.org.br/concursos/TC_DF_24_AUDITOR/arquivos/PADRO_DEFINITIVO_DE_RESPOSTAS___PROVA_DISCURSIVA__ESPECIALIDADE_3.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/TC_DF_24_AUDITOR/arquivos/TCDF_AUDITOR_PROVA_DISCURSIVA__ESPECIALIDADE_3.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/TC_DF_24_AUDITOR/arquivos/PADRO_DEFINITIVO_DE_RESPOSTAS___PROVA_DISCURSIVA__ESPECIALIDADE_3.PDF",
