  "fonte": "https://cdn.cebraspe.org.br/concursos/CPNUJE_24/arquivos/PADRO_DEFINITIVO_DE_RESPOSTA___PROVA_DISCURSIVA___CARGO_17_TECNOLOGIA_DA_INFORMAO.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/CPNUJE_24/arquivos/988_CPNUJE_017_DISC.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/CPNUJE_24/arquivos/PADRO_DEFINITIVO_DE_RESPOSTA___PROVA_DISCURSIVA___CARGO_17_TECNOLOGIA_DA_INFORMAO.PDF",
  "fonte_concurso": "https://www.cebraspe.org.br/concursos/CPNUJE_24",
