  "fonte": "https://cdn.cebraspe.org.br/concursos/CPNUJE_24/arquivos/PADRO_DEFINITIVO_DE_RESPOSTA___PROVA_DISCURSIVA___CARGO_11_CLNICA_MDICA.PDF",
  "fonte_prova": "https://cdn.cebraspe.org.br/concursos/CPNUJE_24/arquivos/988_CPNUJE_011_DISC.PDF",
  "fonte_espelho": "https://cdn.cebraspe.org.br/concursos/CPNUJE_24/arquivos/PADRO_DEFINITIVO_DE_RESPOSTA___PROVA_DISCURSIVA___CARGO_11_CLNICA_MDICA.PDF",
